        for (i in 0...series.length) {
            for (j in 0...series[i].length) {
                min = Math.min(min, series[i][j]);
                max = Math.max(max, series[i][j]);
            }
        }

        var defaultSymbols:Array<String> = ['┼', '┤', '╶', '╴', '─', '╰', '╭', '╮', '╯', '│'];
        var range:Float = Math.abs(max - min);
        var offset:Int = (cfg.offset != null) ? cfg.offset : 3;
        var padding:String = (cfg.padding != null) ? cfg.padding : '           ';
        var height:Int = (cfg.height != null) ? cfg.height : Std.int(range);
        var colors:Array<String> = (cfg.colors != null) ? cfg.colors : [];
        var ratio:Float = (range != 0) ? height / range : 1;
        var min2:Int = Math.round(min * ratio);
        var max2:Int = Math.round(max * ratio);
        var rows:Int = Math.abs(max2 - min2);
        var width:Int = 0;
        for (i in 0...series.length) {
            width = Math.max(width, series[i].length);
        }
        width = width + offset;
        var symbols:Array<String> = (cfg.symbols != null) ? cfg.symbols : defaultSymbols;
        var format:Float->String = (cfg.format != null) ? cfg.format : function (x) {
            return (padding + Std.string(x.toFixed(2))).substr(-padding.length);
        };

        var result:Array<Array<String>> = new Array(rows + 1);
        for (i in 0...rows + 1) {
            result[i] = new Array(width).map(function(_) return ' ');
        }

        for (y in min2...max2 + 1) {
            var label:String = format((rows > 0) ? max - (y - min2) * range / rows : y - min2);
            result[y - min2][Math.max(offset - label.length, 0)] = label;
            result[y - min2][offset - 1] = (y == 0) ? symbols[0] : symbols[1];
        }

        for (j in 0...series.length) {
            var currentColor:String = colors[j % colors.length];
            var y0:Int = Math.round(series[j][0] * ratio) - min2;
            result[rows - y0][offset - 1] = colored(symbols[0], currentColor);

            for (x in 0...series[j].length - 1) {
                var y0:Int = Math.round(series[j][x + 0] * ratio) - min2;
                var y1:Int = Math.round(series[j][x + 1] * ratio) - min2;
                if (y0 == y1) {
                    result[rows - y0][x + offset] = colored(symbols[4], currentColor);
