forward({
  input_ids = null,
  attention_mask = null,
  position_ids = null,
  past_key_values = null,
  inputs_embeds = null,
  use_cache = null,
  output_attentions = null,
  output_hidden_states = null,
  return_dict = null,
}) {
  output_attentions = output_attentions !== null ? output_attentions : this.config.output_attentions;
  output_hidden_states = output_hidden_states !== null ? output_hidden_states : this.config.output_hidden_states;
  use_cache = use_cache !== null ? use_cache : this.config.use_cache;
  return_dict = return_dict !== null ? return_dict : this.config.use_return_dict;

  let batch_size, seq_length;

  if (input_ids && inputs_embeds) {
    throw new Error("You cannot specify both input_ids and inputs_embeds at the same time");
  } else if (input_ids) {
    [batch_size, seq_length] = input_ids.shape;
  } else if (inputs_embeds) {
    [batch_size, seq_length,] = inputs_embeds.shape;
  } else {
    throw new Error("You have to specify either input_ids or inputs_embeds");
  }

  let seq_length_with_past = seq_length;
  let past_key_values_length = 0;

  if (past_key_values !== null) {
    past_key_values_length = past_key_values[0][0].shape[2];
    seq_length_with_past += past_key_values_length;
  }

  if (position_ids === null) {
    const device = input_ids ? input_ids.device : inputs_embeds.device;
    position_ids = torch.arange(past_key_values_length, seq_length + past_key_values_length, {
      dtype: 'long',
      device: device,
    });
    position_ids = position_ids.unsqueeze(0).view(-1, seq_length);
  } else {
    position_ids = position_ids.view(-1, seq_length).long();
  }

  if (inputs_embeds === null) {
    inputs_embeds = this.embed_tokens(input_ids);
  }

  if (attention_mask === null) {
    attention_mask = torch.ones((batch_size, seq_length_with_past), {
      dtype: 'bool',
      device: inputs_embeds.device,
    });
  }

  attention_mask = this._prepare_decoder_attention_mask(attention_mask, [batch_size, seq_length], inputs_embeds, past_key_values_length);

  let hidden_states = inputs_embeds;

  let all_hidden_states = output_hidden_states ? [] : null;
  let all_self_attns = output_attentions ? [] : null;
  let next_decoder_cache = use_cache ? [] : null;

  for (let idx = 0; idx < this.layers.length; idx++) {
    const decoder_layer = this.layers[idx];
    let past_key_value = past_key_values ? past_key_values[idx] : null;

    let layer_outputs;

    if (this.gradient_checkpointing && this.training) {
      if (use_cache) {
        console.warn("`use_cache=True` is incompatible with gradient checkpointing. Setting `use_cache=False`...");
        use_cache = false;
      }

      // Logic for gradient checkpointing (will require further details)
    } else {
      layer_outputs = decoder_layer(hidden_states, {
        attention_mask: attention_mask,
        position_ids: position_ids,
        past_key_value: past_key_value,
        output_attentions: output_attentions,
        use_cache: use_cache,
      });
    }

    hidden_states = layer_outputs[0];

    if (use_cache) {
      next_decoder_cache.push(layer_outputs[2 ? output_attentions : 1]);
    }

    if (output_attentions) {
      all_self_attns.push(layer_outputs[1]);
    }

    if (output_hidden_states) {
      all_hidden_states.push(hidden_states);
    }
  }

  hidden_states = this.norm(hidden_states);

  if (output_hidden_states) {
    all_hidden_states.push(hidden_states);
  }

  if (!return_dict) {
    return [hidden_states, next_decoder_cache, all_hidden_states, all_self_attns].filter(v => v !== null);
  }

  return new BaseModelOutputWithPast({
    last_hidden_state: hidden_states,
    past_key_values: next_decoder_cache,
    hidden_states: all_hidden_states,
    attentions: all_self_attns,
  });
}

