                } catch (e) {
                    throw new ErrorNoBranch(String(e));
                }
            } else {
                try {
                    await exec(`git clone --branch ${shaish} --depth 1 ${sshUrl} ${repoDirBasename}`, {
                        "cwd": workingDirectoryPath
                    });
