    let buttons = document.querySelectorAll('button');
    let allButton = Array.from(buttons).find(btn => btn.textContent.trim() === 'All');
    if (allButton) {
        allButton.click();
    }

    await sleep(2000);  // Wait for the page to load

    // Fetch the first batch to get the total count
    const firstBatch = await fetchPluginData(0, 8);
    const totalCount = firstBatch.count;

