class TokenBucket {
    private tokens: number;
    private lastRefillTimestamp: number;

    /**
     * @param capacity Maximum number of tokens in the bucket.
     * @param refillRate Rate at which the tokens are added per second.
     */
    constructor(private capacity: number, private refillRate: number) {
        this.tokens = capacity;
        this.lastRefillTimestamp = Date.now();
    }

    private refill() {
        const now = Date.now();
        const elapsedTime = (now - this.lastRefillTimestamp) / 1000; // Convert to seconds

        const refillTokens = Math.floor(elapsedTime * this.refillRate);
        this.tokens = Math.min(this.tokens + refillTokens, this.capacity);

        this.lastRefillTimestamp = now;
    }

    /**
     * Try consuming tokens from the bucket.
     * @param tokensToConsume The number of tokens to consume.
     * @returns Whether the tokens were consumed successfully.
     */
    consume(tokensToConsume: number): boolean {
        this.refill();

        if (this.tokens >= tokensToConsume) {
            this.tokens -= tokensToConsume;
            return true;
        }
        return false;
    }
}

