if (isNode) {
    const { performance } = await import('node:perf_hooks');
    performanceNow = performance.now;
} else {
    performanceNow = performance.now.bind(performance); // Ensure correct this binding
}

// ... [rest of the code]

class TokenBucket {
    protected tokens: number;
    protected lastRefillTimestamp: number;

    constructor(protected capacity: number, protected refillRate: number) {
        this.tokens = capacity;
        this.lastRefillTimestamp = performanceNow();
    }

    protected refill() {
        const now = performanceNow();
        const elapsedTime = (now - this.lastRefillTimestamp) / 1000; // Convert to seconds

        const refillTokens = Math.floor(elapsedTime * this.refillRate);
        this.tokens = Math.min(this.tokens + refillTokens, this.capacity);

        this.lastRefillTimestamp = now;
    }

    consume(tokensToConsume: number = 1): boolean {
        this.refill();

        if (this.tokens >= tokensToConsume) {
            this.tokens -= tokensToConsume;
            return true;
        }
        return false;
    }
}

class RateLimiter {
    private tokenBuckets: Map<string, TokenBucket>;

    constructor() {
        this.tokenBuckets = new Map();
    }

    // Retrieve or create a new bucket for a given key
    getBucket(key: string, capacity: number, refillRate: number): TokenBucket {
        if (!this.tokenBuckets.has(key)) {
            this.tokenBuckets.set(key, new TokenBucket(capacity, refillRate));
        }
        return this.tokenBuckets.get(key)!;
    }

    consume(key: string, tokensToConsume: number = 1): boolean {
        const bucket = this.tokenBuckets.get(key);
        if (!bucket) {
            throw new Error(`TokenBucket for key '${key}' not found. Make sure to initialize it first with getBucket().`);
        }
        return bucket.consume(tokensToConsume);
    }
}

