int main()
{
    int sockfd;
    struct sockaddr_in addr;

    // Create a socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Enable SO_REUSEADDR
    int enable = 1;
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &enable, sizeof(int)) < 0) {
        perror("SO_REUSEADDR");
        exit(EXIT_FAILURE);
    }

    // Bind the socket to a specific IP address and port
    memset(&addr, 0, sizeof(struct sockaddr_in));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(12345);  // Port number
    inet_pton(AF_INET, "192.168.1.2", &addr.sin_addr);  // IP address

    if (bind(sockfd, (struct sockaddr *) &addr, sizeof(addr)) < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    printf("Socket successfully bound to %s:%d with SO_REUSEADDR enabled\n", "192.168.1.2", 12345);

    // Now you can use the socket...

    return 0;
}

type Result<T, E extends Error> = { kind: "success", value: T } | { kind: "failure", error: E };

function riskyFunction(): Result<number, Error> {
    try {
        // Some code that may throw an error
        let value = 42;
        return { kind: "success", value: value };
    } catch (error) {
        return { kind: "failure", error: error };
    }
}

function callingFunction() {
    let result = riskyFunction();
    if (result.kind === "failure") {
        console.error(result.error);
        return;
    }
    // Here, TypeScript knows result is { kind: "success", value: number }
    console.log(result.value);
}

