module.exports = {
  rules: {
    "enforce-exception-handling": {
      create: function(context) {
        return {
          CallExpression(node) {
            // Assuming the comment is in the form /* throws */
            const throwsComment = node.leadingComments &&
              node.leadingComments.find(comment => comment.value.trim() === "throws");
            if (!throwsComment) return;

            // Check if this call is inside a try-catch block
            let parent = node.parent;
            while (parent) {
              if (parent.type === "TryStatement") return;
              parent = parent.parent;
            }

            // If we get here, the function call wasn't inside a try-catch block
            context.report({
              node,
              message: "This function can throw an exception and needs to be called inside a try-catch block"
            });
          }
        };
      }
    }
  }
};

